using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class StockLengthPicker {
 public static List<double> Choose(IWin32Window owner,IEnumerable<double> current){using(var f=new Form{Text="Available commercial rebar lengths",ClientSize=new Size(430,370),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=new Font("Segoe UI",10)}){f.Controls.Add(new Label{Text="Check only the lengths available from your supplier.\nThe estimator compares these choices for least offcut waste.",Location=new Point(20,15),Size=new Size(390,60)});var list=new CheckedListBox{Location=new Point(20,85),Size=new Size(390,190),CheckOnClick=true,Font=new Font("Segoe UI",12)};foreach(double length in CommercialBars.Lengths)list.Items.Add(length.ToString("0.00")+" m",current.Contains(length));f.Controls.Add(list);var ok=new Button{Text="Apply",Location=new Point(285,300),Size=new Size(125,40)};List<double> selected=null;ok.Click+=(s,e)=>{selected=Enumerable.Range(0,list.Items.Count).Where(n=>list.GetItemChecked(n)).Select(n=>CommercialBars.Lengths[n]).ToList();if(selected.Count==0){MessageBox.Show(f,"Select at least one commercial length.");return;}f.DialogResult=DialogResult.OK;f.Close();};var cancel=new Button{Text="Cancel",Location=new Point(150,300),Size=new Size(125,40),DialogResult=DialogResult.Cancel};f.Controls.Add(ok);f.Controls.Add(cancel);f.AcceptButton=ok;f.CancelButton=cancel;return f.ShowDialog(owner)==DialogResult.OK?selected:null;}}
}
}
